style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.imgur.com/LJkNx2s.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #3a3a3a !important;
  }

  .navbar, .header, .footer, .container, .game-home-page {
    background-color: rgba(246, 228, 238, 0.85) !important;
    border-radius: 12px !important;
  }

  a, button, .btn-primary {
    color: #fff !important;
    background-color: #F6E4EE !important;
    border: none !important;
    border-radius: 10px !important;
    transition: all 0.3s ease-in-out !important;
  }

  .btn-primary:hover {
    background-color: #CCCCCF !important;
    color: #000 !important;
  }

  .modal-content {
    background-color: rgba(255, 255, 255, 0.9) !important;
  }
}
